typography.css_variables:
/* Typography System */
:root {
  --font-heading: 'Cairo', sans-serif;
  --font-body: 'Cairo', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  --text-display: 4rem;
  --text-h1: 3rem;
  --text-h2: 2.25rem;
  --text-h3: 1.875rem;
  --text-h4: 1.5rem;
  --text-h5: 1.25rem;
  --text-h6: 1.125rem;
  --text-body-lg: 1.125rem;
  --text-body: 1rem;
  --text-body-sm: 0.875rem;
  --text-caption: 0.75rem;
  --text-label: 0.6875rem;

  --leading-display: 1.1;
  --leading-heading: 1.25;
  --leading-subheading: 1.35;
  --leading-body: 1.6;
  --leading-body-compact: 1.4;
  --leading-caption: 1.4;

  --tracking-display: -0.03em;
  --tracking-heading: -0.02em;
  --tracking-subheading: -0.01em;
  --tracking-body: 0em;
  --tracking-label-uppercase: 0.08em;
  --tracking-caption-uppercase: 0.1em;

  --weight-black: 900;
  --weight-extrabold: 800;
  --weight-bold: 700;
  --weight-semibold: 600;
  --weight-medium: 500;
  --weight-regular: 400;
  --weight-light: 300;
}

images.css_helpers:
/* Image utilities */
.img-cover     { width:100%; height:100%; object-fit:cover; }
.img-contain   { width:100%; height:100%; object-fit:contain; }
.img-circle    { border-radius:50%; aspect-ratio:1; object-fit:cover; }
.img-card      { aspect-ratio:16/9; object-fit:cover; width:100%; }
.img-card-sq   { aspect-ratio:1; object-fit:cover; width:100%; }
.img-portrait  { aspect-ratio:3/4; object-fit:cover; width:100%; }
.img-hero      { width:100%; aspect-ratio:16/9; object-fit:cover; }
.img-avatar-sm { width:32px; height:32px; border-radius:50%; object-fit:cover; }
.img-avatar-md { width:48px; height:48px; border-radius:50%; object-fit:cover; }
.img-avatar-lg { width:80px; height:80px; border-radius:50%; object-fit:cover; }
.img-avatar-xl { width:120px; height:120px; border-radius:50%; object-fit:cover; }
.img-overlay   { position:relative; overflow:hidden; }
.img-overlay::after {
  content:''; position:absolute; inset:0;
  background:linear-gradient(to bottom,transparent 40%,rgba(0,0,0,.7) 100%);
}

icons.css:
.icon { display:inline-flex; align-items:center; justify-content:center; flex-shrink:0; }
.icon--xs  { width:12px; height:12px; }
.icon--sm  { width:16px; height:16px; }
.icon--md  { width:20px; height:20px; }
.icon--lg  { width:24px; height:24px; }
.icon--xl  { width:32px; height:32px; }
.icon--2xl { width:40px; height:40px; }
.icon svg  { width:100%; height:100%; }

animations.keyframes:
@keyframes fadeIn { from { opacity:0; } to { opacity:1; } }
@keyframes fadeInUp { from { opacity:0; transform:translateY(24px); } to { opacity:1; transform:translateY(0); } }
@keyframes skeleton { 0%{background-position:-200% 0;} 100%{background-position:200% 0;} }
@keyframes spin { from{transform:rotate(0deg);} to{transform:rotate(360deg);} }
@keyframes pulse { 0%,100%{opacity:1;} 50%{opacity:.5;} }
@keyframes fadeInUp { from { opacity:0; transform:translateY(24px); } to { opacity:1; transform:translateY(0); } }

animations.utility_css:
.animate-fade-in      { animation: fadeIn 300ms cubic-bezier(0, 0, 0.2, 1) both; }
.animate-fade-in-up   { animation: fadeInUp 300ms cubic-bezier(0, 0, 0.2, 1) both; }
.animate-fade-in-down { animation: fadeInDown 300ms cubic-bezier(0, 0, 0.2, 1) both; }
.animate-scale-pop    { animation: scalePop 200ms cubic-bezier(0.4, 0, 0.2, 1); }
.animate-spin         { animation: spin 1s linear infinite; }
.animate-pulse        { animation: pulse 2s ease-in-out infinite; }
.delay-100 { animation-delay:100ms; }
.delay-200 { animation-delay:200ms; }
.delay-300 { animation-delay:300ms; }
.delay-400 { animation-delay:400ms; }
.delay-500 { animation-delay:500ms; }
.skeleton {
  background: linear-gradient(90deg,var(--color-border) 25%,
    var(--color-bg-subtle) 50%,var(--color-border) 75%);
  background-size:200% 100%;
  animation:skeleton 1.5s ease-in-out infinite;
  border-radius:4px;
}
.transition-base { transition:all 300ms cubic-bezier(0.4, 0, 0.2, 1); }
.transition-fast { transition:all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.transition-slow { transition:all 500ms cubic-bezier(0.4, 0, 0.2, 1); }
@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after {
    animation-duration:.01ms !important;
    animation-iteration-count:1 !important;
    transition-duration:.01ms !important;
  }
}
